import{defaults,validate}from'./engine.js';
export function simpleConfig(values,advanced={}){const mode=values.skillMode||'single',target=values.targetPreset||'full';if(!['single','three','custom'].includes(mode)||!['full','half','low','custom'].includes(target))throw Error('請重新選擇攻擊方式與目標。');const c={...defaults,...advanced,atk:Number(values.atk),crit:Number(values.crit),cd:Number(values.cd)};c.ratio=mode==='custom'?Number(values.ratio):100;c.hits=mode==='custom'?Number(values.hits):mode==='three'?3:1;if(target==='custom'){for(const k of ['def','hp','hpPct','orbs'])c[k]=Number(values[k])}else{c.def=defaults.def;c.hp=defaults.hp;c.orbs=defaults.orbs;c.hpPct={full:100,half:50,low:20}[target]}if(!Number.isInteger(c.orbs)||!Number.isInteger(c.seed)||c.seed<0||c.seed>4294967295)throw Error('鬼火與測試種子須為範圍內的整數。');return validate(c)}
export function resultSummary(results){const sorted=[...results].sort((a,b)=>b.mean-a.mean),best=sorted[0];if(!best)throw Error('尚未有試算結果');const tied=sorted.filter(x=>Math.abs(x.mean-best.mean)<1e-6),base=sorted.find(x=>x.set==='none')?.mean??0;return{sorted,best,tied,baseline:base,gain:base>0?(best.mean-base)/base:null}}
